from math import comb
from typing import Final

def calculate_probability(type1_expired: int = 5, type2_expired: int = 3) -> float:
    """Return probability that the chosen case is Type I given 2 expired cans in a random 10-draw."""
    if not (0 <= type1_expired <= 24):
        raise ValueError("type1_expired must be between 0 and 24")
    if not (0 <= type2_expired <= 24):
        raise ValueError("type2_expired must be between 0 and 24")
    total_cans: Final[int] = 24
    n_draw: Final[int] = 10
    k_expired: Final[int] = 2

    def hypergeom(expired: int) -> float:
        if expired < k_expired or expired > n_draw:
            return 0.0
        if n_draw - k_expired > total_cans - expired:
            return 0.0
        return comb(expired, k_expired) * comb(total_cans - expired, n_draw - k_expired) / comb(total_cans, n_draw)

    p_i = hypergeom(type1_expired)
    p_ii = hypergeom(type2_expired)

    p_i_prior = 2 / 3
    p_ii_prior = 1 / 3

    numerator = p_i * p_i_prior
    denominator = numerator + p_ii * p_ii_prior

    if denominator == 0:
        raise ZeroDivisionError("Denominator cannot be zero")

    prob = numerator / denominator
    return round(prob, 2)
