    if wells < 0 or avg_yield < 0 or decrease <= 0:
        raise ValueError("Invalid input: wells, avg_yield must be non-negative, decrease must be positive.")

    # Vertex of the quadratic total = (wells + x)*(avg_yield - x*decrease)
    numerator = avg_yield - wells * decrease
    denominator = 2 * decrease

    if denominator == 0:
        raise ValueError("Decrease cannot be zero.")

    # Compute optimal x as integer (vertex of parabola)
    if numerator % denominator == 0:
        x_opt = numerator // denominator
    else:
        x_opt = numerator // denominator  # floor

    # Ensure x is non-negative
    x_opt = max(0, x_opt)

    return x_opt

