from math import comb
from typing import List

def calculate_probability(n: int, k: int) -> float:
    if not (0 <= k <= n):
        raise ValueError("Invalid parameters")
    if k == 0:
        return 0.0
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num % 2 == 0:
            return num == 2
        i = 3
        while i * i <= num:
            if num % i == 0:
                return False
            i += 2
        return True
    primes = [i for i in range(1, n + 1) if is_prime(i)]
    total_combinations = comb(n, k)
    even_prime = 1 if 2 in primes else 0
    odd_prime = len(primes) - even_prime
    nonprimes = [i for i in range(1, n + 1) if i not in primes]
    odd_nonprime = sum(1 for x in nonprimes if x % 2 == 1)
    even_nonprime = len(nonprimes) - odd_nonprime
    favorable = 0
    for p in range(2, min(k, len(primes)) + 1):
        for i in range(max(0, p - even_prime), min(p, odd_prime) + 1):
            ways_prime = comb(odd_prime, i) * comb(even_prime, p - i)
            for j in range(0, min(k - p, odd_nonprime) + 1):
                ways_nonprime = comb(odd_nonprime, j) * comb(even_nonprime, k - p - j)
                if (i + j) % 2 == 0:
                    favorable += ways_prime * ways_nonprime
    prob = (favorable / total_combinations) * 100
    return round(prob, 1)

