from typing import List, Tuple

def _is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num in (2, 3):
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True


def calculate_probability(n: int, k: int) -> float:
    """
    Calculate the probability that among k randomly chosen tickets from 1..n,
    there are at least 2 prime numbers and the sum of the k numbers is even.
    Returns the result as a percentage rounded to one decimal place.
    """
    if n < 1 or k < 2 or k > n:
        raise ValueError("Invalid parameters: n must be >= 1, k must be between 2 and n inclusive.")
    if k == 2:
        # At least 2 primes means both are primes
        primes = [i for i in range(1, n + 1) if _is_prime(i)]
        total = comb(n, k)
        favorable = 0
        for a, b in combinations(primes, 2):
            if (a + b) % 2 == 0:
                favorable += 1
        return round(100 * favorable / total, 1)

    # For k > 2, brute-force enumeration is feasible for small n (e.g., 30)
    total = comb(n, k)
    favorable = 0
    for combo in combinations(range(1, n + 1), k):
        if sum(_is_prime(num) for num in combo) >= 2 and sum(combo) % 2 == 0:
            favorable += 1
    return round(100 * favorable / total, 1)
