from typing import Union

def find_min_first_payment(debt: Union[int, float], target_percent: float, months: int, decay_ratio: float) -> int:
    if months <= 0:
        raise ValueError("months must be a positive integer")
    if decay_ratio <= 0:
        raise ValueError("decay_ratio must be positive")
    if not (0 <= target_percent <= 1):
        raise ValueError("target_percent must be between 0 and 1 inclusive")

    target_amount = debt * target_percent

    if decay_ratio == 1.0:
        total_factor = months
    else:
        total_factor = (1 - decay_ratio ** months) / (1 - decay_ratio)

    if total_factor <= 0:
        raise ValueError("total_factor cannot be non-positive")

    m = math.ceil(target_amount / total_factor)
    return int(m)
